// OpenCV.js-like pseudocode
let src = cv.imread('table.jpg');
cv.cvtColor(src, src, cv.COLOR_RGBA2GRAY);
cv.equalizeHist(src, src);
cv.GaussianBlur(src, new cv.Size(9,9), 2);
let circles = new cv.Mat();
cv.HoughCircles(src, circles, cv.HOUGH_GRADIENT, 1.2, 20, 50, 30, 10, 60);
```

